if(UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Edit mode required");
void AddDamageFlash(string path){var root=UnityEditor.PrefabUtility.LoadPrefabContents(path);try{if(!root.GetComponent<SoulHunter.Gameplay.VFX.DamageFlash>())root.AddComponent<SoulHunter.Gameplay.VFX.DamageFlash>();UnityEditor.PrefabUtility.SaveAsPrefabAsset(root,path);}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}}
AddDamageFlash("Assets/Prefabs/Player/Player.prefab");AddDamageFlash("Assets/Prefabs/Weapons/Enemy_Entity.prefab");AddDamageFlash("Assets/Prefabs/Bosses/SH10_L01_BossGameplay.prefab");
var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var vfx=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject).FirstOrDefault(g=>g.name=="VFX_Systems");if(!vfx){vfx=new UnityEngine.GameObject("VFX_Systems");UnityEditor.SceneManagement.EditorSceneManager.MoveGameObjectToScene(vfx,scene);}if(!vfx.GetComponent<SoulHunter.Gameplay.VFX.VFXPoolManager>())vfx.AddComponent<SoulHunter.Gameplay.VFX.VFXPoolManager>();
var camera=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject).FirstOrDefault(g=>g.name=="Main Camera");if(!camera)throw new System.Exception("Main Camera not found");if(!camera.GetComponent<SoulHunter.Gameplay.VFX.CameraShake>())camera.AddComponent<SoulHunter.Gameplay.VFX.CameraShake>();
UnityEditor.AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);return new{damageFlashPrefabs=3,vfxManager=vfx.name,cameraShake=camera.name};
